StageStats scaledStageStats(const StageStats& stats, float scale) {
    StageStats result = stats;
    result.minVal *= scale;
    result.p0_1 *= scale;
    result.p1 *= scale;
    result.p5 *= scale;
    result.p10 *= scale;
    result.p25 *= scale;
    result.p50 *= scale;
    result.p95 *= scale;
    result.p99 *= scale;
    result.p99_5 *= scale;
    result.maxVal *= scale;
    return result;
}

